<script setup>
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue';
import { adminRequest } from '../../../lib/publicationUi.js';
const props=defineProps({record:{type:Object,default:null},saving:Boolean,serverError:String});
const emit=defineEmits(['save','close','busy']);
const initial=props.record||{};
const form=ref({titulo:initial.titulo||'',resumen:initial.resumen||'',descripcion:initial.descripcion||'',programa:initial.programa||'',fecha:(initial.fecha_publicacion||'').slice(0,10),URI:initial.uri||'',keywords:(initial.palabras_clave||[]).join(', '),pdfURL:initial.pdfURL||'',imagenURL:initial.imagenURL||''});
const selected=ref(JSON.parse(JSON.stringify(initial.investigadores||[]))), options=ref([]), search=ref(''), error=ref(''), uploading=ref(false), file=ref(null), loading=ref(true);
const busy=computed(()=>props.saving||uploading.value);
watch(uploading,value=>emit('busy',value),{flush:'sync'});
onBeforeUnmount(()=>emit('busy',false));
const filtered=computed(()=>options.value.filter(p=>p.nombre.toLocaleLowerCase('es').includes(search.value.trim().toLocaleLowerCase('es'))));
async function load(){loading.value=true;try{options.value=(await adminRequest('/api/investigadores/obtener')).docs.map(p=>({id:p._id,nombre:p.nombre}));error.value='';}catch(e){error.value=e.message;}finally{loading.value=false;}}
function toggle(person,event){selected.value=event.target.checked?[...selected.value,person]:selected.value.filter(p=>p.id!==person.id);}
async function save(){if(busy.value)return;error.value='';if(!selected.value.length){error.value='Selecciona al menos una persona investigadora.';return;}try{
  if(file.value){if(file.value.type!=='application/pdf')throw new Error('Selecciona un archivo PDF válido.');uploading.value=true;const body=new FormData();body.append('pdf',file.value);body.append('carpeta','investigaciones');const response=await fetch('/api/subir_pdf',{method:'POST',body});const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.error||'No se pudo subir el PDF.');form.value.pdfURL=data.pdfUrl;form.value.imagenURL=data.thumbnailUrl||'';file.value=null;}
  emit('save',{titulo:form.value.titulo,resumen:form.value.resumen,descripcion:form.value.descripcion,programa:form.value.programa,investigadores:selected.value,'Fecha de publicacion':form.value.fecha,URI:form.value.URI,'palabras clave':form.value.keywords,pdfURL:form.value.pdfURL,imagenURL:form.value.imagenURL});
}catch(e){error.value=e.message;}finally{uploading.value=false;}}
onMounted(load);
</script>
<template><form class="modal-box w-11/12 max-w-3xl research-form" @submit.prevent="save"><div class="section-heading"><div><p class="eyebrow">CATÁLOGO ACADÉMICO</p><h2>{{record?'Editar investigación':'Nueva investigación'}}</h2></div><button type="button" class="icon-button" :disabled="busy" aria-label="Cerrar formulario" @click="$emit('close')">×</button></div><p class="subtle">El registro se guarda como borrador. Podrás enviarlo a revisión desde su ficha.</p><p v-if="error||serverError" class="ui-alert error" role="alert">{{error||serverError}}</p><fieldset :disabled="busy"><label class="field-label">Título<input v-model="form.titulo" class="ui-control" required maxlength="500"/></label><div class="form-grid"><label class="field-label">Programa<select v-model="form.programa" class="ui-control" required><option value="" disabled>Selecciona un programa</option><option value="estudios-sociologicos">Estudios sociológicos</option><option value="juridicos-politicos">Estudios jurídicos y políticos</option><option value="tierra-medio-ambiente">Tierra y medio ambiente</option><option value="genero-inclusion">Género e inclusión</option><option value="opinion-publica">Opinión pública</option></select></label><label class="field-label">Fecha de publicación<input v-model="form.fecha" type="date" class="ui-control" required/></label></div><label class="field-label">Resumen<textarea v-model="form.resumen" class="ui-control" rows="4" maxlength="10000" required></textarea></label><label class="field-label">Descripción<textarea v-model="form.descripcion" class="ui-control" rows="5" maxlength="10000" required></textarea></label>
<div class="field-label">Investigadores</div><label class="field-label"><span class="sr-only">Buscar investigadores</span><input v-model="search" type="search" class="ui-control" placeholder="Buscar por nombre…"/></label><p v-if="loading" class="field-help">Cargando investigadores…</p><div class="researcher-options"><label v-for="person in filtered" :key="person.id" class="permission-option"><input type="checkbox" class="checkbox checkbox-sm" :checked="selected.some(p=>p.id===person.id)" @change="toggle(person,$event)"/><span>{{person.nombre}}</span></label></div><p v-if="!loading&&!options.length" class="field-help">No hay investigadores disponibles. Regístralos primero en el módulo Investigadores.</p><div class="inline-tags"><span v-for="person in selected" :key="person.id" class="selection-tag">{{person.nombre}}<button type="button" :aria-label="`Quitar a ${person.nombre}`" @click="selected=selected.filter(p=>p.id!==person.id)">×</button></span></div>
<label class="field-label">Palabras clave<input v-model="form.keywords" class="ui-control" maxlength="3000" placeholder="Universidad, investigación, comunidad"/><span class="field-help">Separa las palabras con comas.</span></label><label class="field-label">Enlace de referencia (opcional)<input v-model="form.URI" type="url" class="ui-control" placeholder="https://…"/></label><label class="field-label">Documento PDF<input type="file" class="file-input file-input-bordered w-full" accept="application/pdf" @change="file=$event.target.files?.[0]||null"/></label><a v-if="form.pdfURL" :href="form.pdfURL" class="document-download" target="_blank" rel="noopener">Ver documento actual ↗</a></fieldset><div class="dialog-actions"><button type="button" class="ui-button" :disabled="busy" @click="$emit('close')">Cancelar</button><button class="ui-button primary" :disabled="busy||loading">{{uploading?'Subiendo PDF…':saving?'Guardando…':record?'Guardar cambios':'Crear borrador'}}</button></div></form></template>
